class Produit:
    def __init__(self, nom, prix_centimes):
        nom = nom.strip()

        if not nom:
            raise ValueError("Le nom du produit est obligatoire.")
        if prix_centimes < 0:
            raise ValueError("Le prix ne peut pas être négatif.")

        self.nom = nom
        self.prix_centimes = prix_centimes

    def description(self):
        prix = self.prix_centimes / 100
        return f"{self.nom} — {prix:.2f} €"

    def prix_pour(self, quantite):
        if quantite < 0:
            raise ValueError("La quantité ne peut pas être négative.")
        return self.prix_centimes * quantite

class Pizza(Produit):
    def __init__(self, nom, prix_centimes, taille):
        super().__init__(nom, prix_centimes)
        self.taille = taille

    def description(self):
        prix = self.prix_centimes / 100
        return f"Pizza {self.nom} ({self.taille}) — {prix:.2f} €"

class Boisson(Produit):
    def __init__(self, nom, prix_centimes, volume_ml):
        super().__init__(nom, prix_centimes)
        self.volume_ml = volume_ml

    def description(self):
        prix = self.prix_centimes / 100
        return f"{self.nom} ({self.volume_ml} ml) — {prix:.2f} €"

def calculer_total_centimes(menu, commande):
    total = 0

    for produit in menu:
        quantite = commande.get(produit.nom, 0)
        total += produit.prix_pour(quantite)

    return total

